const update = $json.body || $json;
const message = update.message || update.edited_message || {};
const text = message.text || update.text || '';
const chatId = message.chat?.id || update.chat_id || null;
const userId = message.from?.id || update.user_id || null;
const messageId = message.message_id || update.message_id || null;
const updateId = update.update_id || null;

if (!chatId) {
  throw new Error('Telegram chat.id is required');
}

return [
  {
    json: {
      raw_message: String(text),
      telegram_chat_id: String(chatId),
      telegram_user_id: userId ? String(userId) : null,
      telegram_message_id: messageId ? String(messageId) : null,
      telegram_update_id: updateId ? String(updateId) : null,
      correlation_id: crypto.randomUUID(),
    },
  },
];

const text = ($json.raw_message || '').trim().toLowerCase();
const approvals = new Set(['setuju', 'iya', 'ya', 'oke', 'ok', 'gas', 'lanjut', 'buat', 'sudah benar', 'sip']);

let intent = 'UNKNOWN';
if (approvals.has(text)) {
  intent = 'APPROVE_DRAFT';
} else if (/kirim.*ulang|kirim.*lagi|resend/.test(text)) {
  intent = 'RESEND_INVOICE';
} else if (/status|sudah terkirim|invoice .* mana/.test(text)) {
  intent = 'GET_STATUS';
} else if (/ganti|ubah|revisi|jadi|tidak usah dp/.test(text) || (/tanpa dp/.test(text) && !/buat|invoice|tagihan/.test(text))) {
  intent = 'UPDATE_DRAFT';
} else if (/invoice|tagihan/.test(text)) {
  intent = 'CREATE_INVOICE';
}

return [
  {
    json: {
      ...$json,
      intent,
      confidence: intent === 'UNKNOWN' ? 0.2 : 0.7,
      intent_source: 'deterministic_prefilter',
    },
  },
];
